async function fetchAllRows<T>(makeQuery:()=>any):Promise<T[]>{const pageSize=1000;const rows:T[]=[];for(let offset=0;;offset+=pageSize){const {data,error}=await makeQuery().range(offset,offset+pageSize-1);if(error)throw new Error(error.message??'Could not load statistics data.');const page=(data??[]) as T[];rows.push(...page);if(page.length<pageSize)return rows}}
function localDate(date:Date){const d=new Date(date);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10)}
function sizeGb(value:unknown){const match=String(value??'').match(/([0-9]+(?:\.[0-9]+)?)\s*(GB|MB)/i);if(!match)return 0;const n=Number(match[1]);return match[2].toUpperCase()==='MB'?n/1000:n}
function networkRank(network:string){return network==='MTN'?0:network==='AT'?1:network==='Telecel'?2:3}
function networkLabel(network:string){return network==='MTN'?'MTN DATA':network==='AT'?'AT DATA':network==='Telecel'?'TELECEL DATA':`${network.toUpperCase()} DATA`}
function groupOrdersByPlan(orders:Row[],bundleById:Map<string,Row>){const categories=new Map<string,Row[]>();for(const order of orders){const bundle=bundleById.get(String(order.bundle_id));const title=String(bundle?.category??bundle?.subcategory??'General').trim()||'General';const list=categories.get(title)??[];list.push(order);categories.set(title,list)}return [...categories.entries()].sort(([a],[b])=>a.localeCompare(b)).map(([category,rows])=>{const plans=new Map<string,Row[]>();for(const order of rows){const bundle=bundleById.get(String(order.bundle_id));const size=String(bundle?.size??'Unknown plan');const list=plans.get(size)??[];list.push(order);plans.set(size,list)}return{category,orders:rows,plans:[...plans.entries()].sort(([a],[b])=>sizeGb(a)-sizeGb(b)).map(([size,items])=>({key:`${category}:${size}`,size,orders:items}))}})}

