export function SettingsAdmin({client,notify,onSettingsChanged}:{client:SupabaseClient;notify:(message:string)=>void;onSettingsChanged?:()=>void}){
 const [user,setUser]=useState<any>(null),[profile,setProfile]=useState({first_name:'',last_name:'',username:'',phone:'',email:''}),[passwords,setPasswords]=useState({current:'',next:'',confirm:''}),[settings,setSettings]=useState({store:{enabled:false,message:'The storefront is temporarily under maintenance. Please check back soon.'},agent:{enabled:false,message:'The agent dashboard is temporarily under maintenance. Please check back soon.'},payments:{checkout:false,deposits:true,feeRatePercent:3}}),[contact,setContact]=useState({phone:'+233249514164',channel:'https://chat.whatsapp.com/EBJ2We2FTzR3cMK3EZ1FyK'}),[loading,setLoading]=useState(true),[saving,setSaving]=useState(false);
 useEffect(()=>{let active=true;async function load(){const [{data:{user:u}},{data:rows,error}]=await Promise.all([client.auth.getUser(),client.from('platform_settings').select('key,value')]);if(!active)return;setUser(u);const meta=u?.user_metadata??{};setProfile({first_name:meta.first_name??'',last_name:meta.last_name??'',username:meta.username??'',phone:meta.phone??'',email:u?.email??''});if(!error){for(const r of rows??[]){if(r.key==='storefront_maintenance')setSettings(s=>({...s,store:{enabled:!!r.value?.enabled,message:r.value?.message??s.store.message}}));if(r.key==='agent_dashboard_maintenance')setSettings(s=>({...s,agent:{enabled:!!r.value?.enabled,message:r.value?.message??s.agent.message}}));if(r.key==='storefront_live_sales')setSettings(s=>({...s,payments:{...s.payments,checkout:r.value?.enabled===true}}));if(r.key==='wallet_deposits_enabled')setSettings(s=>({...s,payments:{...s.payments,deposits:r.value?.enabled===true}}));if(r.key==='paystack_fee_recovery')setSettings(s=>({...s,payments:{...s.payments,feeRatePercent:Number(r.value?.rate_percent??3)}}));if(r.key==='storefront_contact')setContact({phone:r.value?.phone??'+233249514164',channel:r.value?.channel??'https://chat.whatsapp.com/EBJ2We2FTzR3cMK3EZ1FyK'})}}setLoading(false)}void load();return()=>{active=false}},[client]);
 async function saveProfile(event:FormEvent){event.preventDefault();if(!user)return;const emailChanged=profile.email.trim().toLowerCase()!==(user.email??'').toLowerCase();setSaving(true);const {error}=await client.auth.updateUser({email:emailChanged?profile.email.trim():undefined,data:{first_name:profile.first_name.trim(),last_name:profile.last_name.trim(),username:profile.username.trim(),phone:profile.phone.trim()}},emailChanged?{emailRedirectTo:window.location.origin}:undefined);setSaving(false);if(error){const message=/only request this after\s+(\d+)\s+seconds/i.exec(error.message);if(message){notify(`Supabase rate-limited this email change. Wait ${message[1]} seconds, then try again.`);return}if(/email rate limit exceeded|over_email_send_rate_limit/i.test(error.message)){notify('Supabase has reached its Auth email-sending limit. Wait for the quota to reset. The built-in SMTP allows 2 Auth emails per hour per project; configure custom SMTP in Supabase Authentication → SMTP Settings for higher limits.');return}notify(`Could not update admin profile: ${error.message}`);return}notify(emailChanged?'Profile updated. Confirm the new email address using the link sent to you.':'Admin profile updated.')}
 async function changePassword(event:FormEvent){event.preventDefault();if(passwords.next.length<8||passwords.next!==passwords.confirm){notify('Use a password with at least 8 characters and make both new password fields match.');return}const email=user?.email;if(!email){notify('Could not verify the current admin account.');return}setSaving(true);const verify=await client.auth.signInWithPassword({email,password:passwords.current});if(verify.error){setSaving(false);notify('Current password could not be verified.');return}const changed=await client.auth.updateUser({password:passwords.next});setSaving(false);if(changed.error){notify(`Password change failed: ${changed.error.message}`);return}setPasswords({current:'',next:'',confirm:''});notify('Admin password changed.')}
 async function saveMaintenance(event:FormEvent){event.preventDefault();setSaving(true);const [store,agent]=await Promise.all([client.from('platform_settings').update({value:settings.store}).eq('key','storefront_maintenance'),client.from('platform_settings').update({value:settings.agent}).eq('key','agent_dashboard_maintenance')]);setSaving(false);if(store.error||agent.error){notify('Maintenance settings could not be saved. Apply the admin operations migration and confirm admin access.');return}notify('Maintenance settings saved.');onSettingsChanged?.()}
 async function saveContact(event:FormEvent){event.preventDefault();const digits=contact.phone.replace(/\D/g,'');if(digits.length<9){notify('Enter a valid WhatsApp support number.');return}if(contact.channel&&!/^https:\/\/(chat\.)?whatsapp\.com\//i.test(contact.channel.trim())){notify('Enter a valid WhatsApp invite link beginning with https://chat.whatsapp.com/ or https://whatsapp.com/');return}setSaving(true);const {error}=await client.from('platform_settings').update({value:{phone:contact.phone.trim(),channel:contact.channel.trim()}}).eq('key','storefront_contact');setSaving(false);if(error){notify(`WhatsApp contact settings could not be saved: ${error.message}`);return}notify('WhatsApp support number and channel link saved.');onSettingsChanged?.()}
 async function savePayments(event:FormEvent){event.preventDefault();const feeRate=Number(settings.payments.feeRatePercent);if(!Number.isFinite(feeRate)||feeRate<0||feeRate>10){notify('Enter a Paystack fee from 0% to 10%.');return}setSaving(true);const [checkout,deposits,fee]=await Promise.all([client.from('platform_settings').update({value:{enabled:settings.payments.checkout}}).eq('key','storefront_live_sales'),client.from('platform_settings').update({value:{enabled:settings.payments.deposits}}).eq('key','wallet_deposits_enabled'),client.from('platform_settings').update({value:{enabled:true,rate_percent:feeRate}}).eq('key','paystack_fee_recovery')]);setSaving(false);if(checkout.error||deposits.error||fee.error){notify(`Paystack settings could not be saved: ${checkout.error?.message??deposits.error?.message??fee.error?.message}`);return}notify('Paystack availability and transaction fee settings saved.');onSettingsChanged?.()}
 return <div className="ops-settings-grid"><section className="admin-card"><div className="admin-card-heading"><div><h2>Admin Account</h2><p>Update your admin profile, email address, and password.</p></div><span className="ops-chip green">Admin Profile</span></div><form className="ops-settings-form" onSubmit={saveProfile}><div className="ops-two-col"><label>First Name<input value={profile.first_name} onChange={e=>setProfile({...profile,first_name:e.target.value})}/></label><label>Last Name<input value={profile.last_name} onChange={e=>setProfile({...profile,last_name:e.target.value})}/></label><label>Username<input value={profile.username} onChange={e=>setProfile({...profile,username:e.target.value})}/></label><label>Email Address<input type="email" required value={profile.email} onChange={e=>setProfile({...profile,email:e.target.value})}/></label></div><label>Phone Number<input value={profile.phone} onChange={e=>setProfile({...profile,phone:e.target.value})}/></label><button className="ops-primary" disabled={saving||loading}>Update Account</button></form><form className="ops-settings-form ops-password-form" onSubmit={changePassword}><div><b>Password Change</b><small>Leave the password fields empty if you do not want to change your password.</small></div><div className="ops-two-col"><label>Current Password<input type="password" autoComplete="current-password" value={passwords.current} onChange={e=>setPasswords({...passwords,current:e.target.value})}/></label><label>New Password<input type="password" autoComplete="new-password" value={passwords.next} onChange={e=>setPasswords({...passwords,next:e.target.value})}/></label><label className="ops-full">Confirm New Password<input type="password" autoComplete="new-password" value={passwords.confirm} onChange={e=>setPasswords({...passwords,confirm:e.target.value})}/></label></div><button className="ops-primary" disabled={saving||!passwords.current||!passwords.next||!passwords.confirm}>Change Password</button></form></section><section className="admin-card"><div className="admin-card-heading"><div><h2>Maintenance Control</h2><p>Show a maintenance notice on the storefront.</p></div><span className={`ops-chip ${settings.store.enabled||settings.agent.enabled?'amber':'green'}`}>{settings.store.enabled||settings.agent.enabled?'Maintenance On':'System Live'}</span></div><form className="ops-settings-form" onSubmit={saveMaintenance}>{([['store','Storefront'],['agent','Agent Dashboard']] as const).map(([key,label])=><div className="ops-maintenance-card" key={key}><div className="ops-maintenance-head"><div><b>{label}</b><small>{key==='store'?'Customers will see the maintenance message instead of the shop.':'Saved setting for future agent dashboard access.'}</small></div><label className="ops-switch"><input type="checkbox" checked={settings[key].enabled} onChange={e=>setSettings({...settings,[key]:{...settings[key],enabled:e.target.checked}})}/><span/></label></div><label>Message<textarea value={settings[key].message} onChange={e=>setSettings({...settings,[key]:{...settings[key],message:e.target.value}})} maxLength={500}/></label></div>)}<button className="ops-primary" disabled={saving||loading}>Save Maintenance Settings</button></form></section><section className="admin-card"><div className="admin-card-heading"><div><h2>Paystack Availability</h2><p>Control live bundle checkout and wallet top-ups separately.</p></div><span className={`ops-chip ${settings.payments.checkout?'green':settings.payments.deposits?'amber':'amber'}`}>{settings.payments.checkout?'Bundle checkout on':settings.payments.deposits?'Wallet top-ups on':'Unavailable'}</span></div><form className="ops-settings-form" onSubmit={savePayments}><div className="ops-maintenance-card"><div className="ops-maintenance-head"><div><b>Bundle checkout</b><small>Enables customer payments for live data plans. Requires a live Paystack secret and deployed checkout and webhook functions.</small></div><label className="ops-switch"><input type="checkbox" checked={settings.payments.checkout} onChange={e=>setSettings({...settings,payments:{...settings.payments,checkout:e.target.checked}})}/><span/></label></div></div><div className="ops-maintenance-card"><div className="ops-maintenance-head"><div><b>Wallet top-ups</b><small>Enables Paystack wallet deposits. Requires PAYSTACK_SECRET_KEY and the wallet checkout, verify, and webhook functions.</small></div><label className="ops-switch"><input type="checkbox" checked={settings.payments.deposits} onChange={e=>setSettings({...settings,payments:{...settings.payments,deposits:e.target.checked}})}/><span/></label></div></div><label>Paystack transaction charge (%)<input type="number" min="0" max="10" step="0.01" value={settings.payments.feeRatePercent} onChange={e=>setSettings({...settings,payments:{...settings.payments,feeRatePercent:Number(e.target.value)}})}/><small>Added to every Paystack wallet top-up and direct bundle payment. For example, GHS 50.00 at 3% is GHS 51.50 total.</small></label><button className="ops-primary" disabled={saving||loading}>{saving?'Saving…':'Save Paystack Settings'}</button></form></section><section className="admin-card"><div className="admin-card-heading"><div><h2>WhatsApp Contact Settings</h2><p>Update the customer support number and public WhatsApp channel link.</p></div><span className="ops-chip green">Storefront</span></div><form className="ops-settings-form" onSubmit={saveContact}><label>WhatsApp Support Number<input type="tel" value={contact.phone} onChange={e=>setContact({...contact,phone:e.target.value})} placeholder="e.g. +233 24 951 4164" required/><small>Used by the customer support WhatsApp and call buttons.</small></label><label>WhatsApp Channel Invite Link<input type="url" value={contact.channel} onChange={e=>setContact({...contact,channel:e.target.value})} placeholder="https://whatsapp.com/channel/…"/><small>Used by the Join WhatsApp Channel button.</small></label><button className="ops-primary" disabled={saving||loading}>{saving?"Saving…":"Save WhatsApp Details"}</button></form></section></div>
}

export function AgentCashoutPolicySettings({client,notify}:{client:SupabaseClient;notify:(message:string)=>void}){
 const [minimumGross,setMinimumGross]=useState('10.31'),[deductionPercent,setDeductionPercent]=useState('3'),[loading,setLoading]=useState(true),[saving,setSaving]=useState(false);
 useEffect(()=>{let active=true;client.from('platform_settings').select('value').eq('key','agent_cashout_policy').maybeSingle().then(({data,error})=>{if(!active)return;if(error){notify('Agent withdrawal settings could not load. Apply the cashout policy migration.')}else if(data?.value){setMinimumGross(String(data.value.minimum_gross??10.31));setDeductionPercent(String(data.value.deduction_percent??3))}setLoading(false)});return()=>{active=false}},[client,notify]);
 async function save(event:FormEvent){event.preventDefault();const minimum=Number(minimumGross),rate=Number(deductionPercent);if(!Number.isFinite(minimum)||minimum<0.01||minimum>50000||Math.round(minimum*100)!==minimum*100){notify('Set a minimum gross withdrawal from GHS 0.01 to GHS 50,000.00, to two decimal places.');return}if(!Number.isFinite(rate)||rate<0||rate>50){notify('Set the withdrawal deduction from 0% to 50%.');return}setSaving(true);const {error}=await client.from('platform_settings').update({value:{minimum_gross:minimum,deduction_percent:rate}}).eq('key','agent_cashout_policy');setSaving(false);if(error){notify(`Agent withdrawal settings could not be saved: ${error.message}`);return}notify('Agent minimum withdrawal and business share saved.')}
 return <section className="admin-card"><div className="admin-card-heading"><div><h2>Agent Withdrawal Policy</h2><p>Set the minimum gross withdrawal and the business share deducted from agent profit.</p></div><span className="ops-chip green">Agent Cashouts</span></div><form className="ops-settings-form" onSubmit={event=>void save(event)}><label>Minimum gross withdrawal (GHS)<input type="number" min="0.01" max="50000" step="0.01" value={minimumGross} onChange={event=>setMinimumGross(event.target.value)}/><small>This is the amount removed from the agent’s available profit before deducting the business share. The effective minimum also ensures the net transfer meets Paystack’s GHS 10.00 payout minimum.</small></label><label>Business share deduction (%)<input type="number" min="0" max="50" step="0.01" value={deductionPercent} onChange={event=>setDeductionPercent(event.target.value)}/><small>The configured percentage is retained by the business; the remaining amount goes to the agent’s MoMo. Paystack transfer fees are separate.</small></label><button className="ops-primary" disabled={saving||loading}>{saving?'Saving…':'Save Withdrawal Policy'}</button></form></section>
}
